type UnionFind struct {
	parents map[int]int
	sizes   map[int]int
}

func NewUnionFind() *UnionFind {
	return &UnionFind{
		parents: make(map[int]int),
		sizes:   make(map[int]int),
	}
}

func (uf *UnionFind) union(a, b int) {
	fa := uf.find(a)
	fb := uf.find(b)
	if fa != fb {
		uf.parents[fa] = fb
		uf.sizes[fb] = (uf.sizes[fb] + 1)
		if uf.sizes[fa] != 0 {
			uf.sizes[fb] += uf.sizes[fa]
		}
	}
}

func (uf *UnionFind) find(a int) int {
	getOrDefault := func(v int) int {
		if p, ok := uf.parents[v]; ok {
			return p
		}
		return v
	}
	parent := getOrDefault(a)
	for parent != getOrDefault(parent) {
		uf.parents[parent] = getOrDefault(getOrDefault(parent))
		parent = uf.parents[parent]
	}
	return parent
}

func (uf *UnionFind) connected(a, b int) bool {
	return uf.find(a) == uf.find(b)
}

func (uf *UnionFind) getSize(a int) int {
	if s, ok := uf.sizes[uf.find(a)]; ok {
		return s
	}
	return 1
}

