type Trie struct {
	root *TrieNode
}

type TrieNode struct {
	hasWord  bool
	children map[rune]*TrieNode
}

func NewTrie() *Trie {
	return &Trie{root: &TrieNode{children: make(map[rune]*TrieNode)}}
}

func (t *Trie) insert(word string) {
	node := t.root
	for _, ch := range word {
		if _, ok := node.children[ch]; !ok {
			node.children[ch] = &TrieNode{children: make(map[rune]*TrieNode)}
		}
		node = node.children[ch]
	}
	node.hasWord = true
}

func (t *Trie) search(word string) bool {
	node := t.findNode(word)
	if node == nil {
		return false
	}
	return node.hasWord
}

func (t *Trie) startsWith(prefix string) bool {
	return t.findNode(prefix) != nil
}

func (t *Trie) findNode(prefix string) *TrieNode {
	node := t.root
	for _, ch := range prefix {
		next, ok := node.children[ch]
		if !ok {
			return nil
		}
		node = next
	}
	return node
}

type BinaryIndexedTree struct {
	bit []int
}

func NewBinaryIndexedTree(n int) *BinaryIndexedTree {
	return &BinaryIndexedTree{bit: make([]int, n+1)}
}

func NewBinaryIndexedTreeFromArray(nums []int) *BinaryIndexedTree {
	bit := make([]int, len(nums)+1)
	prefix := make([]int, len(bit))
	for i := 1; i <= len(nums); i++ {
		prefix[i] = prefix[i-1] + nums[i-1]
		bit[i] = prefix[i] - prefix[i-lowbit(i)]
	}
	return &BinaryIndexedTree{bit: bit}
}

func (b *BinaryIndexedTree) query(index int) int {
	res := 0
	i := index + 1
	for i > 0 {
		res += b.bit[i]
		i -= lowbit(i)
	}
	return res
}

func (b *BinaryIndexedTree) update(index, x int) {
	value := b.query(index) - b.query(index-1)
	b.add(index, x-value)
}

func (b *BinaryIndexedTree) add(index, x int) {
	i := index + 1
	for i < len(b.bit) {
		b.bit[i] += x
		i += lowbit(i)
	}
}

func lowbit(x int) int {
	return x & -x
}

type BinaryIndexedTreeMax struct {
	bit []int
}

func NewBinaryIndexedTreeMax(n int) *BinaryIndexedTreeMax {
	return &BinaryIndexedTreeMax{bit: make([]int, n+1)}
}

func (b *BinaryIndexedTreeMax) query(index int) int {
	res := 0
	i := index + 1
	for i > 0 {
		if b.bit[i] > res {
			res = b.bit[i]
		}
		i -= lowbit(i)
	}
	return res
}

func (b *BinaryIndexedTreeMax) update(index, x int) {
	i := index + 1
	for i < len(b.bit) {
		if x > b.bit[i] {
			b.bit[i] = x
		}
		i += lowbit(i)
	}
}

type SparseTableMax struct {
	nums []int
	st   [][]int
}

func NewSparseTableMax(nums []int) *SparseTableMax {
	n := len(nums)
	logN := 0
	for (1 << logN) <= n {
		logN++
	}
	st := make([][]int, n*2)
	for i := range st {
		st[i] = make([]int, logN)
	}
	for i := 0; i < n; i++ {
		st[i][0] = nums[i]
	}
	for j := 1; j < logN; j++ {
		for i := 0; i < n; i++ {
			st[i][j] = st[i][j-1]
			if i+(1<<(j-1)) < n {
				if st[i+(1<<(j-1))][j-1] > st[i][j] {
					st[i][j] = st[i+(1<<(j-1))][j-1]
				}
			}
		}
	}
	return &SparseTableMax{nums: nums, st: st}
}

func (s *SparseTableMax) query(left, right int) int {
	if left > right {
		return -1
	}
	length := right - left + 1
	k := 0
	for (1 << (k + 1)) <= length {
		k++
	}
	a := s.st[left][k]
	b := s.st[right-(1<<k)+1][k]
	if a > b {
		return a
	}
	return b
}

type SparseTableMin struct {
	nums []int
	st   [][]int
}

func NewSparseTableMin(nums []int) *SparseTableMin {
	n := len(nums)
	logN := 0
	for (1 << logN) <= n {
		logN++
	}
	st := make([][]int, n*2)
	for i := range st {
		st[i] = make([]int, logN)
		for j := range st[i] {
			st[i][j] = math.MaxInt32 / 2
		}
	}
	for i := 0; i < n; i++ {
		st[i][0] = nums[i]
	}
	for j := 1; j < logN; j++ {
		for i := 0; i < n; i++ {
			st[i][j] = st[i][j-1]
			if i+(1<<(j-1)) < n {
				if st[i+(1<<(j-1))][j-1] < st[i][j] {
					st[i][j] = st[i+(1<<(j-1))][j-1]
				}
			}
		}
	}
	return &SparseTableMin{nums: nums, st: st}
}

func (s *SparseTableMin) query(left, right int) int {
	if left > right {
		return -1
	}
	length := right - left + 1
	k := 0
	for (1 << (k + 1)) <= length {
		k++
	}
	a := s.st[left][k]
	b := s.st[right-(1<<k)+1][k]
	if a < b {
		return a
	}
	return b
}

type PrefixSum2D struct {
	prefix [][]int
}

func NewPrefixSum2D(grid [][]int) *PrefixSum2D {
	m := len(grid)
	n := len(grid[0])
	prefix := make([][]int, m+1)
	for i := range prefix {
		prefix[i] = make([]int, n+1)
	}
	for i := 0; i < m; i++ {
		row := 0
		for j := 0; j < n; j++ {
			row += grid[i][j]
			prefix[i+1][j+1] = prefix[i][j+1] + row
		}
	}
	return &PrefixSum2D{prefix: prefix}
}

func (p *PrefixSum2D) query(up, left, bottom, right int) int {
	return p.prefix[up][left] + p.prefix[bottom+1][right+1] -
		p.prefix[bottom+1][left] - p.prefix[up][right+1]
}

type Graph [][]int

func edgesToGraph(n int, edges [][]int, directed bool) Graph {
	g := make(Graph, n)
	for i := 0; i < n; i++ {
		g[i] = []int{}
	}
	for _, e := range edges {
		a, b := e[0], e[1]
		g[a] = append(g[a], b)
		if !directed {
			g[b] = append(g[b], a)
		}
	}
	return g
}

