func lengthOfLIS(numsInput []int) int {
	nums := unify(numsInput)
	bit := NewBinaryIndexedTreeMax(len(nums) + 1)
	result := 0
	for _, num := range nums {
		l := bit.query(num-1) + 1
		bit.update(num, l)
		if l > result {
			result = l
		}
	}
	return result
}

func unify(nums []int) []int {
	cp := make([]int, len(nums))
	copy(cp, nums)
	sort.Ints(cp)
	numToIndex := make(map[int]int)
	idx := 0
	for _, num := range cp {
		if _, ok := numToIndex[num]; !ok {
			numToIndex[num] = idx
			idx++
		}
	}
	res := make([]int, len(nums))
	for i, num := range nums {
		res[i] = numToIndex[num]
	}
	return res
}

func fastPow(a, exp, mod int64) int64 {
	result := int64(1) % mod
	base := a % mod
	remain := exp
	for remain != 0 {
		if remain%2 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		remain /= 2
	}
	return result
}

func gcd(a, b int) int {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func gcdL(a, b int64) int64 {
	if b == 0 {
		return a
	}
	return gcdL(b, a%b)
}

func lcm(a, b int) int {
	return int((int64(a) * int64(b)) / int64(gcd(a, b)))
}

func lcmL(a, b int64) int64 {
	return (a * b) / gcdL(a, b)
}

