func read() string {
	var b []byte
	for {
		c, err := reader.ReadByte()
		if err != nil {
			break
		}
		if c > ' ' {
			b = append(b, c)
			break
		}
	}
	if len(b) == 0 {
		return ""
	}
	for {
		c, err := reader.ReadByte()
		if err != nil || c <= ' ' {
			break
		}
		b = append(b, c)
	}
	return string(b)
}

