		p[i] = i
	}
	return &UnionFindArray{
		n:       n,
		parents: p,
	}
}

func (uf *UnionFindArray) union(a, b int) {
	fa := uf.find(a)
	fb := uf.find(b)
	if fa != fb {
		uf.parents[fa] = fb
	}
}

func (uf *UnionFindArray) find(a int) int {
	parent := uf.parents[a]
	for parent != uf.parents[parent] {
		uf.parents[parent] = uf.parents[uf.parents[parent]]
		parent = uf.parents[parent]
	}
	return parent
}

func (uf *UnionFindArray) connected(a, b int) bool {
	return uf.find(a) == uf.find(b)
}

type Trie struct {
	root *TrieNode
}

type TrieNode struct {
	hasWord  bool
	children map[rune]*TrieNode
}

func NewTrie() *Trie {
	return &Trie{
		root: &TrieNode{
			hasWord:  false,
			children: make(map[rune]*TrieNode),
		},
	}
}

func (t *Trie) insert(word string) {
	node := t.root
	for _, ch := range word {
		if _, ok := node.children[ch]; !ok {
			node.children[ch] = &TrieNode{
				hasWord:  false,
				children: make(map[rune]*TrieNode),
			}
		}
		node = node.children[ch]
	}
	node.hasWord = true
}

func (t *Trie) search(word string) bool {
	node := t.findNode(word)
	if node == nil {
		return false
	}
	return node.hasWord
}

func (t *Trie) startsWith(prefix string) bool {
	return t.findNode(prefix) != nil
}

func (t *Trie) findNode(prefix string) *TrieNode {
	node := t.root
	for _, ch := range prefix {
		next, ok := node.children[ch]
		if !ok {
			return nil
		}
		node = next
	}
	return node
}

type BinaryIndexedTree struct {
	bit []int
}

func NewBinaryIndexedTree(n int) *BinaryIndexedTree {
	return &BinaryIndexedTree{
		bit: make([]int, n+1),
	}
}

func NewBinaryIndexedTreeFromArray(nums []int) *BinaryIndexedTree {
	bit := make([]int, len(nums)+1)
	prefix := make([]int, len(bit))
	for i := 1; i <= len(nums); i++ {
		prefix[i] = prefix[i-1] + nums[i-1]
		bit[i] = prefix[i] - prefix[i-lowbit(i)]
	}
	return &BinaryIndexedTree{bit: bit}
}

func (b *BinaryIndexedTree) query(index int) int {
	result := 0
	i := index + 1
	for i > 0 {
		result += b.bit[i]
		i -= lowbit(i)
	}
	return result
}

func (b *BinaryIndexedTree) update(index, x int) {
	value := b.query(index) - b.query(index-1)
	b.add(index, x-value)
}

func (b *BinaryIndexedTree) add(index, x int) {
	i := index + 1
	for i < len(b.bit) {
		b.bit[i] += x
		i += lowbit(i)
	}
}

func lowbit(x int) int {
	return x & -x
}

