func (b *BinaryIndexedTreeMax) query(index int) int {
	result := 0
	i := index + 1
	for i > 0 {
		if b.bit[i] > result {
			result = b.bit[i]
		}
		i -= lowbit(i)
	}
	return result
}

func (b *BinaryIndexedTreeMax) update(index, x int) {
	i := index + 1
	for i < len(b.bit) {
		if x > b.bit[i] {
			b.bit[i] = x
		}
		i += lowbit(i)
	}
}

