func requiredLen(n int, x int64) int {
	const MAX = 10000
	queue := []int64{x}
	step := 0
	for len(queue) > 0 {
		next := make([]int64, 0)
		for len(queue) > 0 {
			num := queue[0]
			queue = queue[1:]
			if num < 0 {
				return step
			}
			str := fmt.Sprint(num)
			if len(str) == n {
				return step
			}
			if len(str) > n {
				continue
			}
			digits := make([]bool, 10)
			for _, ch := range str {
				d := toDigit(ch)
				if d <= 1 || digits[d] {
					continue
				}
				digits[d] = true
				next = append(next, num*int64(d))
			}
		}
		sort.Slice(next, func(i, j int) bool { return next[i] > next[j] })
		if len(next) > MAX {
			next = next[:MAX]
		}
		queue = append(queue, next...)
		step++
	}
	return -1
}

