func fastPow(a, exp, mod int64) int64 {
	result := int64(1) % mod
	base := a % mod
	remain := exp
	for remain != 0 {
		if remain%2 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		remain /= 2
	}
	return result
}

