func bitsHighestOneBit(x int) int {
	if x == 0 {
		return 0
	}
	msb := 0
	for (1 << (msb + 1)) <= x {
		msb++
	}
	return 1 << msb
}

func bitsTrailingZeros(x int) int {
	if x == 0 {
		return 0
	}
	cnt := 0
	for (x & 1) == 0 {
		x >>= 1
		cnt++
	}
	return cnt
}

