	i := index + 1
	for i > 0 {
		if b.bit[i] > res {
			res = b.bit[i]
		}
		i -= lowbit(i)
	}
	return res
}

func (b *BinaryIndexedTreeMax) update(index, x int) {
	i := index + 1
	for i < len(b.bit) {
		if x > b.bit[i] {
