func NewPrefixSum2D(grid [][]int) *PrefixSum2D {
	m := len(grid)
	n := len(grid[0])
	prefix := make([][]int, m+1)
	for i := range prefix {
		prefix[i] = make([]int, n+1)
	}
	for i := 0; i < m; i++ {
		row := 0
		for j := 0; j < n; j++ {
			row += grid[i][j]
			prefix[i+1][j+1] = prefix[i][j+1] + row
		}
	}
	return &PrefixSum2D{prefix: prefix}
}

func (p *PrefixSum2D) query(up, left, bottom, right int) int {
	return p.prefix[up][left] + p.prefix[bottom+1][right+1] -
		p.prefix[bottom+1][left] - p.prefix[up][right+1]
}

