func lengthOfLIS(numsInput []int) int {
	nums := unify(numsInput)
	bit := NewBinaryIndexedTreeMax(len(nums) + 1)
	result := 0
	for _, num := range nums {
		l := bit.query(num-1) + 1
		bit.update(num, l)
		if l > result {
			result = l
		}
	}
	return result
}

func unify(nums []int) []int {
	cp := make([]int, len(nums))
	copy(cp, nums)
	sort.Ints(cp)
	m := make(map[int]int)
	idx := 0
	for _, v := range cp {
		if _, ok := m[v]; !ok {
			m[v] = idx
			idx++
		}
	}
	res := make([]int, len(nums))
	for i, v := range nums {
		res[i] = m[v]
	}
	return res
}

func fastPow(a, exp, mod int64) int64 {
	result := int64(1) % mod
	base := a % mod
	remain := exp
	for remain != 0 {
		if remain%2 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		remain /= 2
	}
	return result
}

