func (uf *UnionFind) union(a, b int) {
	fa := uf.find(a)
	fb := uf.find(b)
	if fa != fb {
		uf.parents[fa] = fb
		uf.sizes[fb] = (uf.sizes[fb]) + (uf.sizes[fa])
		if uf.sizes[fb] == 0 {
			uf.sizes[fb] = 1
