type SparseTableMin struct {
	nums []int
	st   [][]int
}

func NewSparseTableMin(nums []int) *SparseTableMin {
	n := len(nums)
	logN := 0
	for (1 << uint(logN)) <= n {
		logN++
	}
	st := make([][]int, n*2)
	for i := range st {
		st[i] = make([]int, logN+1)
		for j := range st[i] {
			st[i][j] = math.MaxInt32 / 2
		}
	}
	for i := 0; i < n; i++ {
		st[i][0] = nums[i]
	}
	for j := 1; j <= logN; j++ {
		for i := 0; i < n; i++ {
			st[i][j] = st[i][j-1]
			if i+(1<<(uint(j-1))) < n {
				if st[i+(1<<(uint(j-1)))][j-1] < st[i][j] {
					st[i][j] = st[i+(1<<(uint(j-1)))][j-1]
				}
			}
		}
	}
	return &SparseTableMin{nums: nums, st: st}
}

func (s *SparseTableMin) query(left, right int) int {
	if left > right {
		return -1
	}
	len := right - left + 1
	k := 0
	for (1 << uint(k+1)) <= len {
		k++
	}
	a := s.st[left][k]
	b := s.st[right-(1<<uint(k))+1][k]
	if a < b {
		return a
	}
	return b
}

