func requiredLen(n int, x int64) int {
	const MAX = 10000
	queue := toArrayDeque([]int64{x})
	step := 0
	for len(queue) > 0 {
		next := make([]int64, 0)
		for len(queue) > 0 {
			num := queue[0]
			queue = queue[1:]
			if num < 0 {
				return step
			}
			str := fmt.Sprint(num)
			if len(str) == n {
				return step
			}
			if len(str) > n {
				continue
			}
			digits := make([]bool, 10)
			for _, ch := range str {
				d := toDigit(ch)
				if d <= 1 || digits[d] {
					continue
				}
				digits[d] = true
				next = append(next, num*int64(d))
			}
		}
		sort.Slice(next, func(i, j int) bool { return next[i] > next[j] })
		if len(next) > MAX {
			queue = append(queue, next[:MAX]...)
		} else {
			queue = append(queue, next...)
		}
		step++
	}
	return -1
}

func requiredLen1(n int, x int64) int {
	queue := toArrayDeque([]int64{x})
	step := 0
	for len(queue) > 0 {
		type pair struct {
			num int64
			str string
		}
		nextQueue := make([]pair, 0)
		maxLen := 0
		for len(queue) > 0 {
			num := queue[0]
			queue = queue[1:]
			if num < 0 {
				return step
			}
			str := fmt.Sprint(num)
			if len(str) == n {
				return step
			}
			if len(str) > n {
				continue
			}
			digits := make([]bool, 10)
			for _, ch := range str {
				digits[toDigit(ch)] = true
			}
			for d := 2; d < 10; d++ {
				if !digits[d] {
					continue
				}
				nextNum := num * int64(d)
				nextStr := fmt.Sprint(nextNum)
				nextQueue = append(nextQueue, pair{num: nextNum, str: nextStr})
				if len(nextStr) > maxLen {
					maxLen = len(nextStr)
				}
			}
		}
		for _, p := range nextQueue {
			queue = append(queue, p.num)
		}
		step++
	}
	return -1
}

