func NewSparseTableMax(nums []int) *SparseTableMax {
	n := len(nums)
	logN := 0
	for (1 << logN) <= n {
		logN++
	}
	st := make([][]int, n*2)
	for i := range st {
		st[i] = make([]int, logN)
	}
	for i := 0; i < n; i++ {
		st[i][0] = nums[i]
	}
	for j := 1; j < logN; j++ {
		for i := 0; i < n; i++ {
			st[i][j] = st[i][j-1]
			if i+(1<<(j-1)) < n {
				if st[i+(1<<(j-1))][j-1] > st[i][j] {
					st[i][j] = st[i+(1<<(j-1))][j-1]
				}
			}
		}
	}
	return &SparseTableMax{nums: nums, st: st}
}

